DECLARE
 people jsonb := $people$[{"id":"mary-cassatt","name":"Mary Cassatt","name_ko":"메리 카사트","source_ids":["cma:3995","nga:1107"],"artwork_ids":["cma-101646","cma-121035","nga-61368","nga-46569","nga-52163"],"profile":{"lifespan":"1844–1926","context":"미국 · 프랑스에서 활동 · 회화·파스텔·판화","description":"미국에서 태어나 프랑스에서 활동한 화가이자 판화가입니다. 여성과 아이가 쉬거나 이동하고 함께 시간을 보내는 장면을 회화·파스텔·판화로 남겼습니다. 인상주의 전시에 참여했으며, 일본 판화에서 얻은 평면적인 색과 구도도 작품에 활용했습니다. 이번 수집에서는 실내와 해변, 뱃놀이의 서로 다른 일상 장면을 볼 수 있습니다.","sources":[{"label":"메트로폴리탄 미술관 · 카사트 작가 해설","url":"https://www.metmuseum.org/essays/mary-stevenson-cassatt-1844-1926"},{"label":"미국 국립미술관 · 카사트 작가 기록","url":"https://www.nga.gov/artists/1107-mary-cassatt"}],"related_post_ids":[]}},{"id":"john-singer-sargent","name":"John Singer Sargent","name_ko":"존 싱어 사전트","source_ids":["cma:2559","cma:287402"],"artwork_ids":["cma-160289","cma-124814","cma-173172","cma-159987","cma-287405"],"profile":{"lifespan":"1856–1925","context":"미국 · 이탈리아 출생 · 회화·수채·드로잉","description":"이탈리아에서 태어나 프랑스에서 공부하고 주로 영국에서 활동한 미국 화가입니다. 전신 초상과 목탄 초상에서 인물의 자세와 표정을 살폈고, 후기에는 여행 중 만난 안뜰과 산악 풍경을 수채로 많이 그렸습니다. 초상화와 풍경, 제1차 세계대전 회화를 준비한 인체 연구를 함께 살펴볼 수 있습니다.","sources":[{"label":"메트로폴리탄 미술관 · 사전트 작가 해설","url":"https://www.metmuseum.org/essays/john-singer-sargent-1856-1925"},{"label":"클리블랜드 미술관 · 사전트의 수채와 활동 지역","url":"https://clevelandart.org/art/1946.293"},{"label":"클리블랜드 미술관 · 도로시 드레이퍼 초상 귀속","url":"https://clevelandart.org/art/2016.630"}],"related_post_ids":[]}},{"id":"albrecht-durer","name":"Albrecht Dürer","name_ko":"알브레히트 뒤러","source_ids":["cma:11617"],"artwork_ids":["cma-108501","cma-123964","cma-141637","cma-113302","cma-140339"],"profile":{"lifespan":"1471–1528","context":"독일 · 르네상스 · 회화·드로잉·판화","description":"뉘른베르크에서 활동한 독일 르네상스의 화가이자 판화가입니다. 목판화와 동판화에서 촘촘한 선으로 인체·동물·사물의 형태와 빛을 표현했습니다. 성서 이야기와 상징적인 인물을 통해 생각을 전달했으며, 이번 소장작에서는 《묵시록》과 《멜랑콜리아 I》 등 서로 다른 판화의 구성을 비교할 수 있습니다.","sources":[{"label":"메트로폴리탄 미술관 · 뒤러와 르네상스 판화","url":"https://www.metmuseum.org/essays/albrecht-durer-1471-1528"},{"label":"클리블랜드 미술관 · 멜랑콜리아 I 해설","url":"https://clevelandart.org/art/1926.211"}],"related_post_ids":[]}},{"id":"james-mcneill-whistler","name":"James McNeill Whistler","name_ko":"제임스 맥닐 휘슬러","source_ids":["cma:3330"],"artwork_ids":["cma-121261","cma-113947","cma-121103","cma-104300","cma-149670"],"profile":{"lifespan":"1834–1903","context":"미국 · 파리·런던에서 활동 · 회화·판화·드로잉","description":"미국에서 태어나 파리와 런던에서 활동한 화가이자 판화가입니다. 색과 선, 형태의 조화를 중시해 작품에 녹턴·하모니 같은 음악 용어를 사용했습니다. 일본 미술의 공간 구성에도 관심을 가졌으며, 초상과 도시의 일상, 수면의 풍경을 다양한 회화와 판화 기법으로 표현했습니다.","sources":[{"label":"메트로폴리탄 미술관 · 휘슬러 작가 해설","url":"https://www.metmuseum.org/essays/james-mcneill-whistler-1834-1903"},{"label":"클리블랜드 미술관 · 녹턴과 음악 용어","url":"https://clevelandart.org/art/1941.89"}],"related_post_ids":[]}},{"id":"georges-seurat","name":"Georges Seurat","name_ko":"조르주 쇠라","source_ids":["cma:1816","met:162405"],"artwork_ids":["cma-135341","cma-135512","met-437654","met-437655","met-437659"],"profile":{"lifespan":"1859–1891","context":"프랑스 · 신인상주의 · 회화·콩테 드로잉","description":"파리에서 활동하며 색의 배치와 시각적 효과를 연구한 프랑스 화가입니다. 작은 색점을 나란히 놓는 회화와, 종이의 질감을 이용해 명암을 만드는 콩테 드로잉을 남겼습니다. 이번 수집에서는 초기 숲과 강변 풍경, 대형 회화를 위한 습작, 공연 장면을 통해 표현 방식의 변화를 따라볼 수 있습니다.","sources":[{"label":"클리블랜드 미술관 · 아니에르 습작과 쇠라 작가 기록","url":"https://clevelandart.org/art/1958.51"},{"label":"메트로폴리탄 미술관 · 서커스의 곁공연 해설","url":"https://www.metmuseum.org/art/collection/search/437654"}],"related_post_ids":[]}}]$people$::jsonb;
 works jsonb := $works$[{"id":"cma-101646","museum":"The Cleveland Museum of Art","title":"After the Bath","title_ko":"목욕 후","artist":"Mary Cassatt","artist_ids":["mary-cassatt"],"artist_status":"identified","date":"1901","medium":"pastel","medium_ko":"파스텔","dimensions":"Sheet: 66 x 100 cm (26 x 39 3/8 in.)","dimensions_ko":"종이 전체: 66 × 100 cm","description":"목욕을 마친 아이와 아이를 돌보는 여성을 그린 파스텔 드로잉입니다. 얼굴은 세밀하게 마무리하고 옷과 배경에는 빠른 선과 색을 남겨, 인물의 표정과 순간적인 몸짓을 함께 보여줍니다.","culture":"America, late 18th-19th Century","accession":"1920.379","source_url":"https://clevelandart.org/art/1920.379","api_url":"https://openaccess-api.clevelandart.org/api/artworks/101646","preview_url":"https://openaccess-cdn.clevelandart.org/1920.379/1920.379_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1920.379/1920.379_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["인물과 일상"],"taxonomy":{"periods":["20th-century"],"movements":["impressionism"],"kind":"drawing","subjects":["figure","daily-life"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1920.379"},{"label":"메트로폴리탄 미술관 · 카사트와 인상주의","url":"https://www.metmuseum.org/essays/mary-stevenson-cassatt-1844-1926"}]},"image_width":900,"image_height":608,"image_bytes":298013,"sha256":"66a89f422ae9b297f43611f9001fa573542537d56322144319a7c42ab73ac1cf","collected_at":"2026-10-13T06:28:57.995Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-121035","museum":"The Cleveland Museum of Art","title":"In the Omnibus","title_ko":"옴니버스 안에서","artist":"Mary Cassatt","artist_ids":["mary-cassatt"],"artist_status":"identified","date":"1890–91","medium":"color drypoint and aquatint","medium_ko":"컬러 드라이포인트와 아쿼틴트","dimensions":"Platemark: 36.6 x 26.8 cm (14 7/16 x 10 9/16 in.)","dimensions_ko":"판흔: 36.6 × 26.8 cm","description":"파리의 대중교통인 옴니버스 안에 여성과 보모, 아이를 배치한 판화입니다. 넓은 색면과 간결한 윤곽에서 일본 목판화의 영향을 볼 수 있으며, 아이에게 향한 시선과 창밖으로 향한 시선이 일상의 서로 다른 관심을 드러냅니다.","culture":"France","accession":"1941.71","source_url":"https://clevelandart.org/art/1941.71","api_url":"https://openaccess-api.clevelandart.org/api/artworks/121035","preview_url":"https://openaccess-cdn.clevelandart.org/1941.71/1941.71_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1941.71/1941.71_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":[],"kind":"print","subjects":["figure","daily-life","interior"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1941.71"}]},"image_width":666,"image_height":900,"image_bytes":237491,"sha256":"d06a154db82c5754b416190a8d2c919987277dd763c1978e5793b0fbcd7960c3","collected_at":"2026-10-13T06:28:58.072Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-160289","museum":"The Cleveland Museum of Art","title":"Portrait of Lisa Colt Curtis","title_ko":"리사 콜트 커티스의 초상","artist":"John Singer Sargent","artist_ids":["john-singer-sargent"],"artist_status":"identified","date":"1898","medium":"oil on canvas","medium_ko":"캔버스에 유채","dimensions":"Framed: 249 x 134 x 9.5 cm (98 1/16 x 52 3/4 x 3 3/4 in.); Unframed: 219.3 x 104.8 cm (86 5/16 x 41 1/4 in.)","dimensions_ko":"액자 포함: 249 × 134 × 9.5 cm; 액자 제외: 219.3 × 104.8 cm","description":"사전트의 친척과 결혼한 리사 콜트 커티스를 전신으로 그린 초상화입니다. 밝은 새틴 드레스와 어두운 실내를 대비시키고, 베네치아 집에서 손님을 맞는 듯한 자세로 인물을 배치했습니다. 오른쪽 위에는 부부에게 보내는 헌사가 남아 있습니다.","culture":"United States","accession":"1998.168","source_url":"https://clevelandart.org/art/1998.168","api_url":"https://openaccess-api.clevelandart.org/api/artworks/160289","preview_url":"https://openaccess-cdn.clevelandart.org/1998.168/1998.168_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1998.168/1998.168_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":[],"kind":"painting","subjects":["figure","interior"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1998.168"}]},"image_width":425,"image_height":900,"image_bytes":171343,"sha256":"9436170a0c6d602c8cf5f9f6ec56321d9d1c7b5797f19c35064efd7915309385","collected_at":"2026-10-13T06:28:58.121Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-124814","museum":"The Cleveland Museum of Art","title":"The Patio","title_ko":"파티오","artist":"John Singer Sargent","artist_ids":["john-singer-sargent"],"artist_status":"identified","date":"1908","medium":"watercolor with traces of gouache over graphite","medium_ko":"흑연 밑그림 위 수채와 일부 과슈","dimensions":"Sheet: 53.2 x 34.6 cm (20 15/16 x 13 5/8 in.)","dimensions_ko":"종이 전체: 53.2 × 34.6 cm","description":"기둥과 아치가 이어지는 안뜰의 공간을 수채로 그렸습니다. 식물과 벽면, 햇빛과 그늘을 빠른 붓질로 구분합니다. 미술관은 사전트의 후기 수채에서 색을 여러 번 쌓기보다 한 번에 자유롭게 섞어 표현하는 방식에 주목합니다.","culture":"America, late 19th-early 20th Century","accession":"1946.293","source_url":"https://clevelandart.org/art/1946.293","api_url":"https://openaccess-api.clevelandart.org/api/artworks/124814","preview_url":"https://openaccess-cdn.clevelandart.org/1946.293/1946.293_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1946.293/1946.293_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["풍경과 빛"],"taxonomy":{"periods":["20th-century"],"movements":[],"kind":"drawing","subjects":["landscape","daily-life"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1946.293"}]},"image_width":589,"image_height":893,"image_bytes":130433,"sha256":"a1f686f6fa383579d3920c7c5535d34706cfe48ddacc61118246d893cff547d9","collected_at":"2026-10-13T06:28:58.168Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-173172","museum":"The Cleveland Museum of Art","title":"In Austrian Tyrol","title_ko":"오스트리아 티롤에서","artist":"John Singer Sargent","artist_ids":["john-singer-sargent"],"artist_status":"identified","date":"1911","medium":"watercolor with traces of graphite","medium_ko":"흑연 흔적이 있는 수채","dimensions":"Sheet: 29.9 x 45.2 cm (11 3/4 x 17 13/16 in.)","dimensions_ko":"종이 전체: 29.9 × 45.2 cm","description":"티롤의 산악 풍경을 낮은 시점에서 가까이 잘라 담은 수채 드로잉입니다. 전경의 바위와 뒤쪽 산의 형태를 맞물리게 배치하고, 푸른색과 녹색의 빠른 붓질로 지형과 빛을 표현합니다.","culture":"America","accession":"1921.1734","source_url":"https://clevelandart.org/art/1921.1734","api_url":"https://openaccess-api.clevelandart.org/api/artworks/173172","preview_url":"https://openaccess-cdn.clevelandart.org/1921.1734/1921.1734_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1921.1734/1921.1734_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["풍경과 빛"],"taxonomy":{"periods":["20th-century"],"movements":[],"kind":"drawing","subjects":["landscape"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1921.1734"}]},"image_width":1263,"image_height":851,"image_bytes":281535,"sha256":"ff4ddc04d2ea10c933a79fa4956f7b0a4a3c385edf7f8a245268b226eebf08e9","collected_at":"2026-10-13T06:28:58.183Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-159987","museum":"The Cleveland Museum of Art","title":"Studies of a Soldier Drinking, for Gassed (recto); Studies of a Male Nude (verso)","title_ko":"《가스 공격》을 위한 물 마시는 병사 연구(앞면); 남성 누드 연구(뒷면)","artist":"John Singer Sargent","artist_ids":["john-singer-sargent"],"artist_status":"identified","date":"1918–19","medium":"charcoal (stumped in places) (left figures) and graphite (right figure); squared in graphite (right figure)","medium_ko":"목탄과 흑연; 일부 문질러 표현하고 흑연 격자선 사용","dimensions":"Sheet: 48.1 x 62.6 cm (18 15/16 x 24 5/8 in.); Overall: 48.1 x 62.5 cm (18 15/16 x 24 5/8 in.)","dimensions_ko":"종이 전체: 48.1 × 62.6 cm; 전체: 48.1 × 62.5 cm","description":"제1차 세계대전을 소재로 한 사전트의 대형 회화 《가스 공격》을 준비하며 그린 연구입니다. 물을 마시는 병사의 자세를 반복해 살폈으며, 뒷면에는 남성 누드 연구가 있습니다. 미술관 이미지가 함께 보여 주는 앞뒷면을 한 장의 작품으로 셉니다.","culture":"America","accession":"1997.256","source_url":"https://clevelandart.org/art/1997.256","api_url":"https://openaccess-api.clevelandart.org/api/artworks/159987","preview_url":"https://openaccess-cdn.clevelandart.org/1997.256/1997.256_print.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1997.256/1997.256_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["인물과 일상"],"taxonomy":{"periods":["20th-century"],"movements":[],"kind":"drawing","subjects":["figure","history"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1997.256"}]},"image_width":3400,"image_height":1303,"image_bytes":1160087,"sha256":"65da96a1c4255e4961629f19621292e0612ace71c5ba4d6d2e77602ac394b998","collected_at":"2026-10-13T06:28:58.198Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-287405","museum":"The Cleveland Museum of Art","title":"Portrait of Dorothy Draper","title_ko":"도로시 드레이퍼의 초상","artist":"John Singer Sargent","artist_ids":["john-singer-sargent"],"artist_status":"identified","date":"1919","medium":"charcoal on laid paper, mounted to thin cardboard","medium_ko":"얇은 판지에 부착한 레이드지에 목탄","dimensions":"Matted: 74.9 x 61 x 0.8 cm (29 1/2 x 24 x 5/16 in.); Image: 60.6 x 47.1 cm (23 7/8 x 18 9/16 in.)","dimensions_ko":"매트 포함: 74.9 × 61 × 0.8 cm; 이미지: 60.6 × 47.1 cm","description":"도로시 드레이퍼의 얼굴과 상반신을 목탄으로 그린 초상입니다. 얼굴의 밝은 부분과 머리카락·배경의 짙은 부분을 대비시키고, 옷과 어깨에는 비교적 가벼운 선을 남겼습니다. 인물의 시선과 목탄의 명암 표현을 살펴볼 수 있습니다.","culture":"America","accession":"2016.630","source_url":"https://clevelandart.org/art/2016.630","api_url":"https://openaccess-api.clevelandart.org/api/artworks/287405","preview_url":"https://openaccess-cdn.clevelandart.org/2016.630/2016.630_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/2016.630/2016.630_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["인물과 일상"],"taxonomy":{"periods":["20th-century"],"movements":[],"kind":"drawing","subjects":["figure"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/2016.630"}]},"image_width":701,"image_height":900,"image_bytes":277019,"sha256":"fa7e5323fdf26629176b208647116813813c384c4b982baceb6e9de48b4fafd0","collected_at":"2026-10-13T06:28:58.224Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-108501","museum":"The Cleveland Museum of Art","title":"Melencolia I","title_ko":"멜랑콜리아 I","artist":"Albrecht Dürer","artist_ids":["albrecht-durer"],"artist_status":"identified","date":"1514","medium":"engraving","medium_ko":"동판 인그레이빙","dimensions":"Platemark: 23.8 x 18.9 cm (9 3/8 x 7 7/16 in.); Sheet: 24.5 x 19.4 cm (9 5/8 x 7 5/8 in.)","dimensions_ko":"판흔: 23.8 × 18.9 cm; 종이 전체: 24.5 × 19.4 cm","description":"날개 달린 인물 곁에 기하학적 입체, 도구, 모래시계와 마방진을 배치한 판화입니다. 미술관은 이 인물을 창조적인 정신과 우울의 의인화로 해설합니다. 다양한 표면에 빛이 닿는 방식과 촘촘한 선의 명암을 함께 살펴볼 수 있습니다.","culture":"Germany","accession":"1926.211","source_url":"https://clevelandart.org/art/1926.211","api_url":"https://openaccess-api.clevelandart.org/api/artworks/108501","preview_url":"https://openaccess-cdn.clevelandart.org/1926.211/1926.211_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1926.211/1926.211_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["신화와 상상"],"taxonomy":{"periods":["early-modern"],"movements":["renaissance"],"kind":"print","subjects":["figure","imagination"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1926.211"},{"label":"메트로폴리탄 미술관 · 뒤러와 르네상스 판화","url":"https://www.metmuseum.org/essays/albrecht-durer-1471-1528"}]},"image_width":707,"image_height":893,"image_bytes":584450,"sha256":"1359b533ac97127a89cd5440267b5884d56409e06e45f74ae072041ff561c94d","collected_at":"2026-10-13T06:28:58.273Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-123964","museum":"The Cleveland Museum of Art","title":"Adam and Eve","title_ko":"아담과 이브","artist":"Albrecht Dürer","artist_ids":["albrecht-durer"],"artist_status":"identified","date":"1504","medium":"engraving","medium_ko":"동판 인그레이빙","dimensions":"Image: 25 x 19.2 cm (9 13/16 x 7 9/16 in.); Sheet: 25.2 x 19.4 cm (9 15/16 x 7 5/8 in.)","dimensions_ko":"이미지: 25 × 19.2 cm; 종이 전체: 25.2 × 19.4 cm","description":"금단의 열매를 먹기 전 아담과 이브를 북유럽의 숲에 배치한 판화입니다. 인체는 고전 조각의 형태를 참고하고, 여러 동물과 나무에는 신학적 의미를 담았습니다. 어두운 숲과 밝은 인체의 대비가 세밀한 선으로 구성되어 있습니다.","culture":"Germany, early 16th Century","accession":"1944.473","source_url":"https://clevelandart.org/art/1944.473","api_url":"https://openaccess-api.clevelandart.org/api/artworks/123964","preview_url":"https://openaccess-cdn.clevelandart.org/1944.473/1944.473_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1944.473/1944.473_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["신화와 상상"],"taxonomy":{"periods":["early-modern"],"movements":["renaissance"],"kind":"print","subjects":["figure","religion-myth","nature"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1944.473"},{"label":"메트로폴리탄 미술관 · 뒤러와 르네상스 판화","url":"https://www.metmuseum.org/essays/albrecht-durer-1471-1528"}]},"image_width":696,"image_height":900,"image_bytes":401387,"sha256":"94e94927a2df5cda9eeb8fe637d4bc85915226743068c1d428b32914a86098d8","collected_at":"2026-10-13T06:28:58.295Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-141637","museum":"The Cleveland Museum of Art","title":"Knight, Death, and the Devil","title_ko":"기사, 죽음과 악마","artist":"Albrecht Dürer","artist_ids":["albrecht-durer"],"artist_status":"identified","date":"1513","medium":"engraving","medium_ko":"동판 인그레이빙","dimensions":"Sheet: 24.4 x 19 cm (9 5/8 x 7 1/2 in.)","dimensions_ko":"종이 전체: 24.4 × 19 cm","description":"말을 탄 기사가 죽음과 악마를 지나 어두운 협곡을 통과하는 장면입니다. 모래시계와 해골은 유한한 삶을 암시하고, 말과 갑옷, 바위의 서로 다른 표면은 정교한 선으로 표현됩니다. 미술관은 이를 올바른 길을 지키는 힘에 관한 이미지로 해설합니다.","culture":"Germany","accession":"1965.231","source_url":"https://clevelandart.org/art/1965.231","api_url":"https://openaccess-api.clevelandart.org/api/artworks/141637","preview_url":"https://openaccess-cdn.clevelandart.org/1965.231/1965.231_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1965.231/1965.231_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["신화와 상상"],"taxonomy":{"periods":["early-modern"],"movements":["renaissance"],"kind":"print","subjects":["figure","imagination","nature"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1965.231"},{"label":"메트로폴리탄 미술관 · 뒤러와 르네상스 판화","url":"https://www.metmuseum.org/essays/albrecht-durer-1471-1528"}]},"image_width":694,"image_height":893,"image_bytes":577030,"sha256":"ce3e874e1449757ee99bd13fb0a8786ab05ced14d93a6fa1c56ae4bb23fd69ba","collected_at":"2026-10-13T06:28:58.344Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-113302","museum":"The Cleveland Museum of Art","title":"The Four Horsemen, from The Apocalypse","title_ko":"《묵시록》의 네 기사","artist":"Albrecht Dürer","artist_ids":["albrecht-durer"],"artist_status":"identified","date":"c. 1498","medium":"woodcut","medium_ko":"목판화","dimensions":"Sheet: 40 x 28.8 cm (15 3/4 x 11 5/16 in.)","dimensions_ko":"종이 전체: 40 × 28.8 cm","description":"요한계시록을 그림으로 옮긴 《묵시록》 연작의 한 장입니다. 네 기사의 옷자락과 구름, 말발굽 아래 인물들을 같은 방향으로 몰아 장면의 움직임을 강조했습니다. 이 소장본은 종이 뒷면에 본문 글자가 없는 인쇄본입니다.","culture":"Germany, late 15th-early 16th Century","accession":"1932.313","source_url":"https://clevelandart.org/art/1932.313","api_url":"https://openaccess-api.clevelandart.org/api/artworks/113302","preview_url":"https://openaccess-cdn.clevelandart.org/1932.313/1932.313_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1932.313/1932.313_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["신화와 상상"],"taxonomy":{"periods":["early-modern"],"movements":["renaissance"],"kind":"print","subjects":["figure","religion-myth"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1932.313"},{"label":"메트로폴리탄 미술관 · 뒤러와 르네상스 판화","url":"https://www.metmuseum.org/essays/albrecht-durer-1471-1528"}]},"image_width":644,"image_height":893,"image_bytes":573345,"sha256":"cd5a4ec9f2c5d29c1c2d63c5448e7ad68ea863b7c6fd2eeeab4ee1ae532a1ac6","collected_at":"2026-10-13T06:28:58.364Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-140339","museum":"The Cleveland Museum of Art","title":"The Virgin and Child with a Monkey","title_ko":"원숭이와 함께 있는 성모자","artist":"Albrecht Dürer","artist_ids":["albrecht-durer"],"artist_status":"identified","date":"c. 1498","medium":"engraving","medium_ko":"동판 인그레이빙","dimensions":"Image: 19 x 7.9 cm (7 1/2 x 3 1/8 in.)","dimensions_ko":"이미지: 19 × 7.9 cm","description":"낮은 울타리로 둘러싸인 정원에 성모와 아기 예수, 쇠사슬에 묶인 원숭이를 배치했습니다. 아이가 든 새와 원숭이는 미술관 해설에서 신학적 상징으로 다뤄집니다. 인물과 동물, 뒤편 풍경을 촘촘한 선으로 연결한 판화입니다.","culture":"Germany, late 15th Century-early 16th Century","accession":"1964.29","source_url":"https://clevelandart.org/art/1964.29","api_url":"https://openaccess-api.clevelandart.org/api/artworks/140339","preview_url":"https://openaccess-cdn.clevelandart.org/1964.29/1964.29_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1964.29/1964.29_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["신화와 상상"],"taxonomy":{"periods":["early-modern"],"movements":["renaissance"],"kind":"print","subjects":["figure","religion-myth","nature"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1964.29"},{"label":"메트로폴리탄 미술관 · 뒤러와 르네상스 판화","url":"https://www.metmuseum.org/essays/albrecht-durer-1471-1528"}]},"image_width":594,"image_height":893,"image_bytes":490084,"sha256":"fd20721e55e252efb535ea17674972ad0d00ec2013f79dbfa274ed11a6217e11","collected_at":"2026-10-13T06:28:58.386Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-121261","museum":"The Cleveland Museum of Art","title":"The Violin Player","title_ko":"바이올린 연주자","artist":"James McNeill Whistler","artist_ids":["james-mcneill-whistler"],"artist_status":"identified","date":"c. 1890–94","medium":"oil on canvas","medium_ko":"캔버스에 유채","dimensions":"Unframed: 79 x 53.3 cm (31 1/8 x 21 in.)","dimensions_ko":"액자 제외: 79 × 53.3 cm","description":"어두운 배경 앞에 앉은 여성을 그린 회화입니다. 인물의 얼굴과 밝은 옷을 짙은 배경에서 드러내고, 무릎 부근의 악기와 함께 상반신을 가까이 담았습니다. 제한된 색채와 부드러운 명암으로 구성한 초상입니다.","culture":"America","accession":"1942.1133","source_url":"https://clevelandart.org/art/1942.1133","api_url":"https://openaccess-api.clevelandart.org/api/artworks/121261","preview_url":"https://openaccess-cdn.clevelandart.org/1942.1133/1942.1133_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1942.1133/1942.1133_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":[],"kind":"painting","subjects":["figure","performance"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1942.1133"}]},"image_width":589,"image_height":893,"image_bytes":380926,"sha256":"3acae14478c4fd990fda94c01b3ac181f2d27fae6c9a847f7541248ea750bbd1","collected_at":"2026-10-13T06:28:58.405Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-113947","museum":"The Cleveland Museum of Art","title":"Japanese Woman Painting a Fan (recto); Standing Woman Holding Up Her Dress (verso)","title_ko":"부채에 그림을 그리는 일본 여성(앞면); 치맛자락을 들어 올린 여성(뒷면)","artist":"James McNeill Whistler","artist_ids":["james-mcneill-whistler"],"artist_status":"identified","date":"c. 1872","medium":"black chalk and pastel","medium_ko":"검은 초크와 파스텔","dimensions":"Sheet: 27.9 x 17.6 cm (11 x 6 15/16 in.); Secondary Support: 38.5 x 28.9 cm (15 3/16 x 11 3/8 in.)","dimensions_ko":"종이 전체: 27.9 × 17.6 cm; 2차 지지체: 38.5 × 28.9 cm","description":"앞면에는 부채를 든 여성과 옷의 무늬를 색과 선으로 표현하고, 뒷면에는 서 있는 여성의 자세를 간결하게 그렸습니다. 미술관은 일본 미술에 대한 휘슬러의 관심과 나비 모양 서명을 설명합니다. 앞뒷면은 한 장의 작품으로 기록했습니다.","culture":"America","accession":"1933.222","source_url":"https://clevelandart.org/art/1933.222","api_url":"https://openaccess-api.clevelandart.org/api/artworks/113947","preview_url":"https://openaccess-cdn.clevelandart.org/1933.222/1933.222_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1933.222/1933.222_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":[],"kind":"drawing","subjects":["figure","daily-life"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1933.222"}]},"image_width":900,"image_height":699,"image_bytes":314164,"sha256":"91ae27c51918ebbfc6668b83d4e44f3d5c7105e85f62371027960a3311bd6882","collected_at":"2026-10-13T06:28:58.420Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-121103","museum":"The Cleveland Museum of Art","title":"Nocturne","title_ko":"녹턴","artist":"James McNeill Whistler","artist_ids":["james-mcneill-whistler"],"artist_status":"identified","date":"1878","medium":"lithograph on chine collé","medium_ko":"차이나 콜레 기법을 사용한 석판화","dimensions":"Sheet: 17.1 x 26 cm (6 3/4 x 10 1/4 in.)","dimensions_ko":"종이 전체: 17.1 × 26 cm","description":"잔잔한 수면과 배, 멀리 있는 건물을 회색조로 나타낸 판화입니다. 음악 용어인 ‘녹턴’을 제목으로 삼아 구체적인 장소보다 색조와 선, 형태가 이루는 분위기에 주목하게 합니다. 밝고 어두운 층이 수면과 도시의 거리를 나눕니다.","culture":"America","accession":"1941.89","source_url":"https://clevelandart.org/art/1941.89","api_url":"https://openaccess-api.clevelandart.org/api/artworks/121103","preview_url":"https://openaccess-cdn.clevelandart.org/1941.89/1941.89_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1941.89/1941.89_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["풍경과 빛"],"taxonomy":{"periods":["modern"],"movements":[],"kind":"print","subjects":["landscape"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1941.89"}]},"image_width":1263,"image_height":844,"image_bytes":910346,"sha256":"def0153ddddf4c5a80d428211275af4592ee71defa3c02fd89aa624f9381dc2d","collected_at":"2026-10-13T06:28:58.473Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-104300","museum":"The Cleveland Museum of Art","title":"The Old Rag Woman, No. 10","title_ko":"넝마를 모으는 노파, 제10번","artist":"James McNeill Whistler","artist_ids":["james-mcneill-whistler"],"artist_status":"identified","date":"1858","medium":"etching with chine collé","medium_ko":"차이나 콜레 기법을 사용한 에칭","dimensions":"Plate: 20.8 x 14.8 cm (8 3/16 x 5 13/16 in.); Sheet: 27.3 x 20.8 cm (10 3/4 x 8 3/16 in.)","dimensions_ko":"판: 20.8 × 14.8 cm; 종이 전체: 27.3 × 20.8 cm","description":"문간에 앉은 여성을 어두운 실내와 넝마 꾸러미 사이에 배치한 판화입니다. 당시 가난한 사람들이 모아 제지업자에게 팔던 넝마를 소재로, 노년과 도시의 빈곤을 다룹니다. 문틀의 빛과 실내의 그림자가 인물의 자세를 드러냅니다.","culture":"America","accession":"1922.438","source_url":"https://clevelandart.org/art/1922.438","api_url":"https://openaccess-api.clevelandart.org/api/artworks/104300","preview_url":"https://openaccess-cdn.clevelandart.org/1922.438/1922.438_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1922.438/1922.438_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":["realism"],"kind":"print","subjects":["figure","daily-life","interior"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1922.438"}]},"image_width":647,"image_height":893,"image_bytes":511225,"sha256":"6510feafa36786c533fabab9ebd76f4060e651654d224844f2953b1d27c5fb98","collected_at":"2026-10-13T06:28:58.495Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-149670","museum":"The Cleveland Museum of Art","title":"The Wine Glass","title_ko":"와인잔","artist":"James McNeill Whistler","artist_ids":["james-mcneill-whistler"],"artist_status":"identified","date":"1858","medium":"etching","medium_ko":"에칭","dimensions":"Sheet: 21.4 x 17.3 cm (8 7/16 x 6 13/16 in.); Image: 8.3 x 5.5 cm (3 1/4 x 2 3/16 in.)","dimensions_ko":"종이 전체: 21.4 × 17.3 cm; 이미지: 8.3 × 5.5 cm","description":"어두운 바탕에 짧은 줄기가 있는 잔 하나를 배치한 작은 판화입니다. 잔의 테두리와 표면에 남긴 밝은 선, 바닥의 그림자가 투명한 유리의 형태를 구분합니다. 단일 사물을 선과 명암으로 표현하는 방식을 살펴볼 수 있습니다.","culture":"America","accession":"1979.61","source_url":"https://clevelandart.org/art/1979.61","api_url":"https://openaccess-api.clevelandart.org/api/artworks/149670","preview_url":"https://openaccess-cdn.clevelandart.org/1979.61/1979.61_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1979.61/1979.61_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["꽃과 사물"],"taxonomy":{"periods":["modern"],"movements":[],"kind":"print","subjects":["still-life"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1979.61"}]},"image_width":610,"image_height":893,"image_bytes":435809,"sha256":"7ab3754fd97600c3d7836b3bc64493b3ffba28aa09cc0c6e3207422a825f044b","collected_at":"2026-10-13T06:28:58.516Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-135341","museum":"The Cleveland Museum of Art","title":"At the Concert Parisien","title_ko":"콩세르 파리지앵에서","artist":"Georges Seurat","artist_ids":["georges-seurat"],"artist_status":"identified","date":"1887–88","medium":"conté crayon heightened with white chalk on cream handmade modern laid paper","medium_ko":"크림색 수제 레이드지에 흰 초크로 강조한 콩테 크레용","dimensions":"Sheet: 31.4 x 23.6 cm (12 3/8 x 9 5/16 in.)","dimensions_ko":"종이 전체: 31.4 × 23.6 cm","description":"모자를 쓴 관객들 사이로 무대의 여성 가수를 바라보게 구성한 드로잉입니다. 콩테 크레용이 종이의 질감에 닿으며 만드는 밝고 어두운 면을 이용해, 카페 공연장의 인물과 공간을 윤곽선 없이 드러냅니다.","culture":"France, 19th century","accession":"1958.344","source_url":"https://clevelandart.org/art/1958.344","api_url":"https://openaccess-api.clevelandart.org/api/artworks/135341","preview_url":"https://openaccess-cdn.clevelandart.org/1958.344/1958.344_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1958.344/1958.344_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":[],"kind":"drawing","subjects":["figure","performance","interior"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1958.344"}]},"image_width":685,"image_height":893,"image_bytes":630511,"sha256":"29d5478a15e341c6e0f11103c949c190ac8c3642ef2a79a89b1653212cd49491","collected_at":"2026-10-13T06:28:58.536Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"cma-135512","museum":"The Cleveland Museum of Art","title":"Study for \"Bathers at Asnières\"","title_ko":"《아니에르의 물놀이》를 위한 연구","artist":"Georges Seurat","artist_ids":["georges-seurat"],"artist_status":"identified","date":"c. 1883–84","medium":"oil on wood panel","medium_ko":"목판에 유채","dimensions":"Framed: 32 x 41 x 5 cm (12 5/8 x 16 1/8 x 1 15/16 in.); Unframed: 15.7 x 24.9 cm (6 3/16 x 9 13/16 in.)","dimensions_ko":"액자 포함: 32 × 41 × 5 cm; 액자 제외: 15.7 × 24.9 cm","description":"센강을 따라 쉬거나 물놀이하는 인물들을 그린 대형 회화를 준비하기 위한 유채 습작입니다. 밝은 색으로 야외의 빛을 나타내면서 인물과 지형을 단단한 형태로 구성했습니다. 완성작에 이르는 구도 연구의 한 단계를 보여줍니다.","culture":"France, 19th century","accession":"1958.51","source_url":"https://clevelandart.org/art/1958.51","api_url":"https://openaccess-api.clevelandart.org/api/artworks/135512","preview_url":"https://openaccess-cdn.clevelandart.org/1958.51/1958.51_web.jpg","image_url":"https://openaccess-cdn.clevelandart.org/1958.51/1958.51_print.jpg","license":"CC0","license_evidence":{"share_license_status":"CC0"},"policy_url":"https://www.clevelandart.org/open-access","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":["post-impressionism"],"kind":"painting","subjects":["figure","daily-life","landscape"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://clevelandart.org/art/1958.51"},{"label":"메트로폴리탄 미술관 · 후기인상주의","url":"https://www.metmuseum.org/essays/post-impressionism"}]},"image_width":1263,"image_height":796,"image_bytes":886537,"sha256":"981c645737956bd3ba7e5290f816ac9f416da5823662b9a8b9ba12de61ce15d2","collected_at":"2026-10-13T06:28:58.554Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"met-437654","museum":"The Metropolitan Museum of Art","title":"Circus Sideshow (Parade de cirque)","title_ko":"서커스의 곁공연","artist":"Georges Seurat","artist_ids":["georges-seurat"],"artist_status":"identified","date":"1887–88","medium":"Oil on canvas","medium_ko":"캔버스에 유채","dimensions":"39 1/4 x 59 in. (99.7 x 149.9 cm)","dimensions_ko":"99.7 × 149.9 cm","description":"서커스 앞에서 관객을 모으기 위해 펼치는 밤의 공연을 그렸습니다. 연주자와 관객을 수평으로 나누고, 인공조명 아래의 인물과 악기를 작은 색점으로 구성했습니다. 쇠라의 점묘 기법과 정적인 무대 배치를 함께 살펴볼 수 있습니다.","culture":"","accession":"61.101.17","source_url":"https://www.metmuseum.org/art/collection/search/437654","api_url":"https://collectionapi.metmuseum.org/public/collection/v1/objects/437654","preview_url":"https://images.metmuseum.org/CRDImages/ep/web-large/DP375450_cropped.jpg","image_url":"https://images.metmuseum.org/CRDImages/ep/original/DP375450_cropped.jpg","license":"CC0","license_evidence":{"isPublicDomain":true},"policy_url":"https://www.metmuseum.org/hubs/open-access","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":["post-impressionism"],"kind":"painting","subjects":["figure","performance"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://www.metmuseum.org/art/collection/search/437654"},{"label":"메트로폴리탄 미술관 · 후기인상주의","url":"https://www.metmuseum.org/essays/post-impressionism"}]},"image_width":600,"image_height":401,"image_bytes":457746,"sha256":"66cfa744803eca9129f6d0c03de831e68f5ff401207e92aad04d272486782d02","collected_at":"2026-10-13T06:28:58.576Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"met-437655","museum":"The Metropolitan Museum of Art","title":"The Forest at Pontaubert","title_ko":"퐁토베르의 숲","artist":"Georges Seurat","artist_ids":["georges-seurat"],"artist_status":"identified","date":"1881","medium":"Oil on canvas","medium_ko":"캔버스에 유채","dimensions":"31 1/8 x 24 5/8 in. (79.1 x 62.5 cm)","dimensions_ko":"79.1 × 62.5 cm","description":"길게 뻗은 나무와 숲 바닥을 세로형 화면에 담은 초기 풍경화입니다. 나무 사이의 빛과 잎의 색을 작은 붓질로 나누어 표현했습니다. 이후의 점묘 작품과 비교하며 쇠라가 색과 표면을 연구하던 과정을 볼 수 있습니다.","culture":"","accession":"1985.237","source_url":"https://www.metmuseum.org/art/collection/search/437655","api_url":"https://collectionapi.metmuseum.org/public/collection/v1/objects/437655","preview_url":"https://images.metmuseum.org/CRDImages/ep/web-large/DT2165.jpg","image_url":"https://images.metmuseum.org/CRDImages/ep/original/DT2165.jpg","license":"CC0","license_evidence":{"isPublicDomain":true},"policy_url":"https://www.metmuseum.org/hubs/open-access","themes":["풍경과 빛"],"taxonomy":{"periods":["modern"],"movements":[],"kind":"painting","subjects":["landscape","nature"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://www.metmuseum.org/art/collection/search/437655"}]},"image_width":499,"image_height":625,"image_bytes":186578,"sha256":"b69b49e48febb723755f62f19fc1c9e8efed8309ecf5a11c52335020c55041c6","collected_at":"2026-10-13T06:28:58.593Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"met-437659","museum":"The Metropolitan Museum of Art","title":"View of the Seine","title_ko":"센강 풍경","artist":"Georges Seurat","artist_ids":["georges-seurat"],"artist_status":"identified","date":"1882–83","medium":"Oil on wood","medium_ko":"목판에 유채","dimensions":"6 1/4 x 9 3/4 in. (15.9 x 24.8 cm)","dimensions_ko":"15.9 × 24.8 cm","description":"센강의 물과 배, 맞은편 건물을 가로로 긴 작은 화면에 담았습니다. 짧은 붓질로 수면의 반사와 강변의 색을 나누어 표현합니다. 나무판 위에 남긴 초기 유채 풍경으로, 세부보다 전체 색과 배치에 주목해 볼 수 있습니다.","culture":"","accession":"59.16.5","source_url":"https://www.metmuseum.org/art/collection/search/437659","api_url":"https://collectionapi.metmuseum.org/public/collection/v1/objects/437659","preview_url":"https://images.metmuseum.org/CRDImages/ep/web-large/DP-19197-001.jpg","image_url":"https://images.metmuseum.org/CRDImages/ep/original/DP-19197-001.jpg","license":"CC0","license_evidence":{"isPublicDomain":true},"policy_url":"https://www.metmuseum.org/hubs/open-access","themes":["풍경과 빛"],"taxonomy":{"periods":["modern"],"movements":[],"kind":"painting","subjects":["landscape"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://www.metmuseum.org/art/collection/search/437659"}]},"image_width":599,"image_height":405,"image_bytes":151845,"sha256":"3baa1fac1e8f7587840974120eb6580faf99614ba56452fa39e85eedc156cfdc","collected_at":"2026-10-13T06:28:58.612Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"nga-61368","museum":"National Gallery of Art","title":"Little Girl in a Blue Armchair","title_ko":"파란 안락의자의 소녀","artist":"Mary Cassatt","artist_ids":["mary-cassatt"],"artist_status":"identified","date":"1878","medium":"oil on canvas","medium_ko":"캔버스에 유채","dimensions":"overall: 89.5 × 129.8 cm (35 1/4 × 51 1/8 in.); framed: 109.22 × 152.72 × 6.35 cm (43 × 60 1/8 × 2 1/2 in.)","dimensions_ko":"전체: 89.5 × 129.8 cm; 액자 포함: 109.22 × 152.72 × 6.35 cm","description":"파란 의자에 몸을 기댄 소녀와 맞은편 의자의 작은 개를 그린 실내화입니다. 무늬가 있는 가구와 비스듬한 배치를 통해 아이의 편안한 자세를 보여줍니다. 미술관은 배경 구성에 드가의 도움이 있었다고 설명하며, 작품의 작가는 카사트로 표기합니다.","culture":"American","accession":"1983.1.18","source_url":"https://www.nga.gov/artworks/61368-little-girl-blue-armchair","preview_url":"https://api.nga.gov/iiif/6dc9ca49-ea8c-4314-985a-ba2cfc3965cd/full/1200,/0/default.jpg","image_url":"https://api.nga.gov/iiif/6dc9ca49-ea8c-4314-985a-ba2cfc3965cd/full/full/0/default.jpg","license":"CC0","license_evidence":{"object_media_public_domain":true,"object_notice":"This object’s media is free and in the public domain."},"policy_url":"https://www.nga.gov/terms-and-notices","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":["impressionism"],"kind":"painting","subjects":["figure","daily-life","interior","nature"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://www.nga.gov/artworks/61368-little-girl-blue-armchair"},{"label":"메트로폴리탄 미술관 · 카사트와 인상주의","url":"https://www.metmuseum.org/essays/mary-stevenson-cassatt-1844-1926"}]},"image_width":1200,"image_height":804,"image_bytes":274407,"sha256":"14ee084e09b0201dd33afa48ce7614f5ae901d5accce0edcb7fc95a7dcb08e58","collected_at":"2026-10-13T06:29:00.620Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"nga-46569","museum":"National Gallery of Art","title":"The Boating Party","title_ko":"뱃놀이","artist":"Mary Cassatt","artist_ids":["mary-cassatt"],"artist_status":"identified","date":"1893/1894","medium":"oil on canvas","medium_ko":"캔버스에 유채","dimensions":"overall: 90 x 117.3 cm (35 7/16 x 46 3/16 in.); framed: 112.1 x 137.8 cm (44 1/8 x 54 1/4 in.)","dimensions_ko":"전체: 90 × 117.3 cm; 액자 포함: 112.1 × 137.8 cm","description":"노를 젓는 남성과 아이를 안은 여성을 위에서 비스듬히 바라본 장면입니다. 어두운 남성의 실루엣, 노란 배의 곡선, 푸른 물을 큰 색면으로 나누고 수평선을 화면 위쪽에 두었습니다. 미술관은 이 평면적 구성에서 일본 판화의 영향을 설명합니다.","culture":"American","accession":"1963.10.94","source_url":"https://www.nga.gov/artworks/46569-boating-party","preview_url":"https://api.nga.gov/iiif/f8b6727d-6998-4f2a-9708-8694b9c69f54/full/1200,/0/default.jpg","image_url":"https://api.nga.gov/iiif/f8b6727d-6998-4f2a-9708-8694b9c69f54/full/full/0/default.jpg","license":"CC0","license_evidence":{"object_media_public_domain":true,"object_notice":"This object’s media is free and in the public domain."},"policy_url":"https://www.nga.gov/terms-and-notices","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":["post-impressionism"],"kind":"painting","subjects":["figure","daily-life","landscape"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://www.nga.gov/artworks/46569-boating-party"},{"label":"메트로폴리탄 미술관 · 후기인상주의","url":"https://www.metmuseum.org/essays/post-impressionism"}]},"image_width":1200,"image_height":919,"image_bytes":264047,"sha256":"121c6ac01a1b6fa719e40564c3fb136d4f61eeae7a79593de45b168cbf3a47fa","collected_at":"2026-10-13T06:29:02.290Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"nga-52163","museum":"National Gallery of Art","title":"Children Playing on the Beach","title_ko":"해변에서 노는 아이들","artist":"Mary Cassatt","artist_ids":["mary-cassatt"],"artist_status":"identified","date":"1884","medium":"oil on canvas","medium_ko":"캔버스에 유채","dimensions":"overall: 97.4 × 74.2 cm (38 3/8 × 29 3/16 in.); framed: 117.79 × 94.3 × 6.99 cm (46 3/8 × 37 1/8 × 2 3/4 in.)","dimensions_ko":"전체: 97.4 × 74.2 cm; 액자 포함: 117.79 × 94.3 × 6.99 cm","description":"바닷가 모래 위에서 양동이와 삽으로 노는 두 아이를 그렸습니다. 아이들의 몸짓을 화면 가까이 배치하고, 뒤편에는 바다와 작은 배들을 간결하게 남겼습니다. 일상적인 놀이에 몰두하는 아이들의 모습이 중심을 이룹니다.","culture":"American","accession":"1970.17.19","source_url":"https://www.nga.gov/artworks/52163-children-playing-beach","preview_url":"https://api.nga.gov/iiif/20818b10-1f66-4186-ac55-af70e3586084/full/1200,/0/default.jpg","image_url":"https://api.nga.gov/iiif/20818b10-1f66-4186-ac55-af70e3586084/full/full/0/default.jpg","license":"CC0","license_evidence":{"object_media_public_domain":true,"object_notice":"This object’s media is free and in the public domain."},"policy_url":"https://www.nga.gov/terms-and-notices","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":["impressionism"],"kind":"painting","subjects":["figure","daily-life","landscape"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 해설","url":"https://www.nga.gov/artworks/52163-children-playing-beach"},{"label":"메트로폴리탄 미술관 · 카사트와 인상주의","url":"https://www.metmuseum.org/essays/mary-stevenson-cassatt-1844-1926"}]},"image_width":1200,"image_height":1581,"image_bytes":411980,"sha256":"08e238f7fe4e1f1315ecc0c2f1126239f8617a4e4c64545c3cd9558db6a38a44","collected_at":"2026-10-13T06:29:04.550Z","title_ko_status":"working_translation","themes_status":"editorial_classification"}]$works$::jsonb;
BEGIN
 LOCK TABLE public.artists, public.artworks, public.artwork_artists IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(people) item JOIN public.artists a ON a.id=item->>'id' WHERE a.name IS DISTINCT FROM item->>'name' OR a.name_ko IS DISTINCT FROM item->>'name_ko' OR to_jsonb(a.source_ids) IS DISTINCT FROM item->'source_ids' OR a.profile IS DISTINCT FROM item->'profile') THEN
  RAISE EXCEPTION 'Artist ID conflict: no existing content was changed';
 END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(works) item JOIN public.artworks w ON w.id=item->>'id' WHERE w.data IS DISTINCT FROM item - 'artist_ids') THEN
  RAISE EXCEPTION 'Artwork ID conflict: no existing content was changed';
 END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(works) item JOIN public.artwork_artists link ON link.artwork_id=item->>'id' WHERE NOT (item->'artist_ids' ? link.artist_id)) THEN
  RAISE EXCEPTION 'Conflicting artist attribution: no existing content was changed';
 END IF;
 INSERT INTO public.artists(id,name,name_ko,source_ids,profile)
 SELECT item->>'id',item->>'name',item->>'name_ko',ARRAY(SELECT jsonb_array_elements_text(item->'source_ids')),item->'profile' FROM jsonb_array_elements(people) item ON CONFLICT (id) DO NOTHING;
 INSERT INTO public.artworks(id,data)
 SELECT item->>'id',item - 'artist_ids' FROM jsonb_array_elements(works) item ON CONFLICT (id) DO NOTHING;
 INSERT INTO public.artwork_artists(artwork_id,artist_id)
 SELECT item->>'id',person FROM jsonb_array_elements(works) item CROSS JOIN LATERAL jsonb_array_elements_text(item->'artist_ids') person ON CONFLICT DO NOTHING;
END;
$catalog_addition$;
